renderVectorPoly = {
  const svg = d3.select("#vector-poly-container").append("svg")
    .attr("width", size).attr("height", size).style("border", "1px solid #eee");

  const center = size / 2;
  const radius = 72;
  const sides = 6; // Hexagon

  const vertices = d3.range(sides).map(i =&gt; {
    const angle = (i / sides) * Math.PI * 2 - Math.PI / 2;
    return [center + radius * Math.cos(angle), center + radius * Math.sin(angle)];
  });

  const lineGenerator = d3.line().curve(d3.curveLinearClosed);

  svg.append("path")
    .attr("d", lineGenerator(vertices))
    .attr("fill", themeColor);

  svg.selectAll("circle")
    .data(vertices).enter().append("circle")
    .attr("cx", d =&gt; d[0]).attr("cy", d =&gt; d[1]).attr("r", 5)
    .attr("fill", "white").attr("stroke", "#333");
}

renderRasterPoly = {
  const svg = d3.select("#raster-poly-container").append("svg")
    .attr("width", size).attr("height", size).style("border", "1px solid #eee");

  for (let i = 0; i &lt; res; i++) {
    for (let j = 0; j &lt; res; j++) {
      const x = (i - res/2) / (res/2.5);
      const y = (j - res/2) / (res/2.5);

      const inHex = (Math.abs(x) &lt; 0.8 && Math.abs(x*0.5 + y*0.8) &lt; 0.8 && Math.abs(x*0.5 - y*0.8) &lt; 0.8);

      svg.append("rect")
        .attr("x", i * cellSize).attr("y", j * cellSize)
        .attr("width", cellSize).attr("height", cellSize)
        .attr("fill", inHex ? themeColor : "#f2f2f2")
        .attr("stroke", "#fff").attr("stroke-width", 2);
    }
  }
}

Vector data model
Three basic vector types exist: points, lines, and polygons. Points are the fundamental unit of the vector data model. They make up everything! In the health context, points often map to the location of facilities, points of interest, or homes. Lines are simply multiple points stitched together with straight line segments. This allows us to represent things like roads, rivers, or even the movement of people. Polygons extend the concept of lines by stitching together points with line segments to form an enclosed area.

{
  const width = 800;
  const height = 210;

  // Adjusted Y coordinates to shift geometry up (original ~100-250 range reduced)
  const basePoints = [
    [60, 100], [130, 70], [210, 110], [170, 180], [80, 170]
  ];

  const svg = d3.create("svg")
      .attr("viewBox", [0, 0, width, height])
      .style("width", "100%")
      .style("height", "auto")
      .style("font-family", "sans-serif");

  const categories = [
    { label: "Points", xOff: 0, type: "point" },
    { label: "Line", xOff: 260, type: "line" },
    { label: "Polygon", xOff: 520, type: "polygon" }
  ];

  const g = svg.selectAll("g")
    .data(categories)
    .join("g")
    .attr("transform", d =&gt; `translate(${d.xOff}, 0)`);

  g.append("text")
    .attr("x", 130)
    .attr("y", 30)
    .attr("text-anchor", "middle")
    .attr("font-weight", "bold")
    .attr("fill", "#333")
    .text(d =&gt; d.label);

  g.filter(d =&gt; d.type === "polygon")
    .append("polygon")
    .attr("points", basePoints.map(p =&gt; p.join(",")).join(" "))
    .attr("fill", themeColor)
    .attr("fill-opacity", 0.2)
    .attr("stroke", "#333")
    .attr("stroke-width", 2);

  g.filter(d =&gt; d.type !== "point")
    .append("path")
    .attr("d", d =&gt; {
      const lineGen = d3.line();
      return d.type === "polygon" 
        ? lineGen([...basePoints, basePoints[0]]) 
        : lineGen(basePoints);
    })
    .attr("fill", "none")
    .attr("stroke", "#333")
    .attr("stroke-width", 2);

  g.selectAll("circle")
    .data(basePoints)
    .join("circle")
    .attr("cx", d =&gt; d[0])
    .attr("cy", d =&gt; d[1])
    .attr("r", 6)
    .attr("fill", themeColor)
    .attr("stroke", "#fff")
    .attr("stroke-width", 1.5);

  return svg.node();
}






All vector data links geometry to descriptive attributes. This data is typically structured in a table where each row represents a unique record tied to a specific spatial geometry. We can use this attribute to conduct queries of our data that leverage both the what and the where of our data. For example, given a dataset of hospitals and county boundaries we can ask the question, “How many Acute Care Hosptials lie within 5 miles of each county’s boundaries?”.

