drawGeometry = {
  const svg = d3.create("svg").attr("width", 150).attr("height", 100);
  svg.selectAll("circle").data(data).join("circle")
    .attr("cx", d =&gt; d.x).attr("cy", d =&gt; d.y).attr("r", d =&gt; d.r)
    .attr("fill", "none").attr("stroke", "#bdc3c7").attr("stroke-dasharray", "3,3");
  return svg.node();
}

drawSpatial = {
  const svg = d3.create("svg").attr("width", 150).attr("height", 100);
  const g = svg.selectAll("g").data(data).join("g");

  g.append("circle")
    .attr("cx", d =&gt; d.x).attr("cy", d =&gt; d.y).attr("r", d =&gt; d.r)
    .attr("fill", d =&gt; d.color).attr("fill-opacity", 0.7).attr("stroke", "#2c3e50");

  g.append("text")
    .attr("x", d =&gt; d.x).attr("y", d =&gt; d.y + 5).attr("text-anchor", "middle")
    .style("fill", "white").style("font-size", "12px").style("font-weight", "bold").style("pointer-events", "none")
    .text(d =&gt; d.label);

  return svg.node();
}

