  type: "sequential", scheme: "blues", domain: [minVal, maxVal], legend: false
});
data = FileAttachment("data/allmortality_20202024_ca.geojson").json()

columnData = data.features
  .map(f =&gt; f.properties.value)
  .filter(v =&gt; v != null && !isNaN(v))

numClasses = 5;
minVal = d3.min(columnData);
maxVal = d3.max(columnData);
meanVal = d3.mean(columnData);
stdDev = d3.deviation(columnData);

getClassIndex = (breaks) =&gt; {
  return (x) =&gt; {
    for (let i = 0; i &lt; breaks.length - 1; i++) {
      if (x &gt;= breaks[i] && x &lt;= breaks[i+1]) return `Class ${i + 1}`;
    }
    return x &lt; breaks[0] ? `Class 1` : `Class ${breaks.length - 1}`;
  };
}

quantileBreaks = Array.from({length: numClasses + 1}, (_, i) =&gt; d3.quantile(columnData, i / numClasses))
equalBreaks = Array.from({length: numClasses + 1}, (_, i) =&gt; minVal + (i * (maxVal - minVal) / numClasses));
jenksBreaks = {
  const ss = await require("simple-statistics@7.8.3");
  return ss.ckmeans(columnData, numClasses).map(cluster =&gt; d3.min(cluster)).concat(maxVal);
}
sdBreaks = [
  minVal, 
  meanVal - 1.5 * stdDev, 
  meanVal - 0.5 * stdDev, 
  meanVal + 0.5 * stdDev, 
  meanVal + 1.5 * stdDev, 
  maxVal
].sort((a, b) =&gt; a - b);

colorDomain = ["Class 1", "Class 2", "Class 3", "Class 4", "Class 5"];
colorRange = ["#eff3ff", "#bdd7e7", "#6baed6", "#3182bd", "#08519c"];

renderStackedRow = (breaks) =&gt; html`
  &lt;div style="width: 100%;"&gt;
    &lt;div style="display: flex; gap: 24px; align-items: center; width: 100%; flex-wrap: wrap;"&gt;
