            type: "mercator",
            domain: data
          }, 
          color: { domain: colorDomain, range: colorRange, legend: false },
          marks: [
            Plot.geo(data, {
              fill: f =&gt; getClassIndex(breaks)(f.properties.value),
              stroke: "#ffffff",
