// Figure 2: Analysis Tools Visual (Abstract spatial processing / buffer analysis schema)
createCardCanvas(400, 220, (ctx, w, h) =&gt; {
  const centerX = w / 2;
  const centerY = h / 2;

  // Draw grid background to represent coordinate tracking
  ctx.strokeStyle = "#e9ecef";
  ctx.lineWidth = 1;
  for (let x = 20; x &lt; w; x += 20) {
    ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
  }
  for (let y = 20; y &lt; h; y += 20) {
    ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
  }

  // Draw background survey vectors/lines
  ctx.strokeStyle = "#dee2e6";
  ctx.lineWidth = 1.5;
  ctx.setLineDash([4, 4]);
  ctx.beginPath();
  ctx.moveTo(centerX - 120, centerY - 60); ctx.lineTo(centerX + 120, centerY + 60);
  ctx.moveTo(centerX - 120, centerY + 60); ctx.lineTo(centerX + 120, centerY - 60);
  ctx.stroke();
  ctx.setLineDash([]); // Reset dash line

  // Draw proximity buffer zone
  ctx.fillStyle = "rgba(13, 110, 253, 0.08)";
  ctx.strokeStyle = "#0d6efd";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(centerX, centerY, 65, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw outer intersection points (representing intersected data records)
  const points = [
    {x: centerX - 40, y: centerY - 30},
    {x: centerX + 50, y: centerY - 15},
    {x: centerX - 20, y: centerY + 45},
    {x: centerX + 35, y: centerY + 35}
  ];

  ctx.fillStyle = "#dc3545";
  points.forEach(p =&gt; {
    ctx.beginPath();
    ctx.arc(p.x, p.y, 4, 0, 2 * Math.PI);
    ctx.fill();
  });

  // Draw focal point (representing the facility or exposure source)
  ctx.fillStyle = "#212529";
  ctx.beginPath();
  ctx.arc(centerX, centerY, 6, 0, 2 * Math.PI);
  ctx.fill();
})






